-- Чудо Обувь / демонстрационный экзамен, задание 1.
-- Import into phpMyAdmin at server level. Requires CREATE DATABASE access.
CREATE DATABASE IF NOT EXISTS chudo_obuv CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE chudo_obuv;
SET NAMES utf8mb4;

CREATE TABLE roles (
    id TINYINT UNSIGNED PRIMARY KEY,
    name VARCHAR(60) NOT NULL UNIQUE
) ENGINE=InnoDB;

CREATE TABLE users (
    id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
    login VARCHAR(64) COLLATE utf8mb4_bin NOT NULL UNIQUE,
    last_name VARCHAR(100) NOT NULL,
    first_name VARCHAR(100) NOT NULL,
    patronymic VARCHAR(100) NOT NULL,
    role_id TINYINT UNSIGNED NOT NULL,
    FOREIGN KEY (role_id) REFERENCES roles(id)
) ENGINE=InnoDB;

CREATE TABLE categories (
    id SMALLINT UNSIGNED PRIMARY KEY,
    name VARCHAR(80) NOT NULL UNIQUE
) ENGINE=InnoDB;

CREATE TABLE subcategories (
    id SMALLINT UNSIGNED PRIMARY KEY,
    category_id SMALLINT UNSIGNED NOT NULL,
    name VARCHAR(80) NOT NULL,
    UNIQUE (category_id, name),
    FOREIGN KEY (category_id) REFERENCES categories(id)
) ENGINE=InnoDB;

CREATE TABLE manufacturers (
    id SMALLINT UNSIGNED PRIMARY KEY,
    name VARCHAR(100) NOT NULL UNIQUE
) ENGINE=InnoDB;

CREATE TABLE products (
    id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
    subcategory_id SMALLINT UNSIGNED NOT NULL,
    manufacturer_id SMALLINT UNSIGNED NOT NULL,
    name VARCHAR(200) NOT NULL,
    image_file VARCHAR(128) NOT NULL,
    description TEXT NOT NULL,
    composition TEXT NOT NULL,
    price DECIMAL(10,2) NOT NULL CHECK (price >= 0),
    UNIQUE (manufacturer_id, name),
    FOREIGN KEY (subcategory_id) REFERENCES subcategories(id),
    FOREIGN KEY (manufacturer_id) REFERENCES manufacturers(id)
) ENGINE=InnoDB;

CREATE TABLE sizes (
    id SMALLINT UNSIGNED PRIMARY KEY,
    size_value DECIMAL(4,1) NOT NULL UNIQUE CHECK (size_value > 0)
) ENGINE=InnoDB;

CREATE TABLE stock_items (
    id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
    product_id INT UNSIGNED NOT NULL,
    size_id SMALLINT UNSIGNED NOT NULL,
    available_quantity INT UNSIGNED NOT NULL,
    UNIQUE (product_id, size_id),
    FOREIGN KEY (product_id) REFERENCES products(id),
    FOREIGN KEY (size_id) REFERENCES sizes(id)
) ENGINE=InnoDB;

CREATE TABLE orders (
    id INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
    ordered_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    customer_id INT UNSIGNED NOT NULL,
    FOREIGN KEY (customer_id) REFERENCES users(id)
) ENGINE=InnoDB;

CREATE TABLE order_items (
    order_id INT UNSIGNED NOT NULL,
    stock_item_id INT UNSIGNED NOT NULL,
    quantity INT UNSIGNED NOT NULL CHECK (quantity > 0),
    unit_price DECIMAL(10,2) NOT NULL CHECK (unit_price >= 0),
    PRIMARY KEY (order_id, stock_item_id),
    FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,
    FOREIGN KEY (stock_item_id) REFERENCES stock_items(id)
) ENGINE=InnoDB;

CREATE SQL SECURITY INVOKER VIEW order_totals AS
SELECT o.id, o.ordered_at, o.customer_id,
       COALESCE(SUM(oi.quantity * oi.unit_price), 0) AS total_amount
FROM orders AS o
LEFT JOIN order_items AS oi ON oi.order_id = o.id
GROUP BY o.id, o.ordered_at, o.customer_id;

START TRANSACTION;










COMMIT;
